@pytest.mark.django_db
class TestAdminBannerListView:
    def test_list_banners_staff(self, staff_client):
        Banner.objects.create(
            title="B1", image=SimpleUploadedFile("b1.jpg", b"\xff\xd8\xff", content_type="image/jpeg")
        )
        Banner.objects.create(
            title="B2", image=SimpleUploadedFile("b2.jpg", b"\xff\xd8\xff", content_type="image/jpeg")
        )
        url = reverse("catalog:admin-banner-list")
        response = staff_client.get(url)
        assert response.status_code == status.HTTP_200_OK
        assert response.data["count"] >= 2

    def test_list_banners_forbidden_for_regular_user(self, regular_client):
        url = reverse("catalog:admin-banner-list")
        response = regular_client.get(url)
        assert response.status_code == status.HTTP_403_FORBIDDEN

    def test_create_banner(self, staff_client):
        url = reverse("catalog:admin-banner-list")
        img = SimpleUploadedFile("banner.jpg", _make_jpeg_bytes(), content_type="image/jpeg")
        payload = {
            "title": "New Banner",
            "subtitle": "Sub",
            "eyebrow": "Eyebrow",
            "image": img,
            "cta_text": "Shop now",
            "cta_link": "/products",
            "secondary_cta_text": "Explore",
            "secondary_cta_link": "#categories",
            "display_order": 0,
            "is_active": True,
        }
        response = staff_client.post(url, payload, format="multipart")
        assert response.status_code == status.HTTP_201_CREATED
        assert Banner.objects.filter(title="New Banner").exists()

    def test_create_banner_invalid_image_type(self, staff_client):
        url = reverse("catalog:admin-banner-list")
        gif_file = SimpleUploadedFile("banner.gif", b"GIF89a", content_type="image/gif")
        payload = {
            "title": "Bad Banner",
            "image": gif_file,
            "display_order": 0,
            "is_active": True,
        }
        response = staff_client.post(url, payload, format="multipart")
        assert response.status_code == status.HTTP_400_BAD_REQUEST

    def test_create_banner_image_too_large(self, staff_client):
        url = reverse("catalog:admin-banner-list")
        big_img = SimpleUploadedFile(
            "big_banner.jpg",
            b"\xff\xd8\xff\xe0" + b"\x00" * (11 * 1024 * 1024),
            content_type="image/jpeg",
        )
        payload = {
            "title": "Huge Banner",
            "image": big_img,
            "display_order": 0,
            "is_active": True,
        }
        response = staff_client.post(url, payload, format="multipart")
        assert response.status_code == status.HTTP_400_BAD_REQUEST

    def test_create_banner_forbidden_for_regular_user(self, regular_client):
        url = reverse("catalog:admin-banner-list")
        img = SimpleUploadedFile("b.jpg", b"\xff\xd8\xff", content_type="image/jpeg")
        payload = {"title": "Denied", "image": img, "display_order": 0, "is_active": True}
        response = regular_client.post(url, payload, format="multipart")
        assert response.status_code == status.HTTP_403_FORBIDDEN


@pytest.mark.django_db
class TestAdminBannerDetailView:
    def _create_banner(self, title="Banner"):
        return Banner.objects.create(
            title=title,
            image=SimpleUploadedFile(f"{title}.jpg", b"\xff\xd8\xff", content_type="image/jpeg"),
        )

    def test_retrieve_banner(self, staff_client):
        banner = self._create_banner("Retrieve Me")
        url = reverse("catalog:admin-banner-detail", kwargs={"pk": banner.pk})
        response = staff_client.get(url)
        assert response.status_code == status.HTTP_200_OK
        assert response.data["title"] == "Retrieve Me"

    def test_update_banner(self, staff_client):
        banner = self._create_banner("Old Title")
        url = reverse("catalog:admin-banner-detail", kwargs={"pk": banner.pk})
        img = SimpleUploadedFile("upd.jpg", _make_jpeg_bytes(), content_type="image/jpeg")
        payload = {
            "title": "New Title",
            "image": img,
            "display_order": 1,
            "is_active": False,
        }
        response = staff_client.put(url, payload, format="multipart")
        assert response.status_code == status.HTTP_200_OK
        banner.refresh_from_db()
        assert banner.title == "New Title"
        assert not banner.is_active

    def test_partial_update_banner(self, staff_client):
        banner = self._create_banner("Partial Banner")
        url = reverse("catalog:admin-banner-detail", kwargs={"pk": banner.pk})
        response = staff_client.patch(url, {"title": "Patched Title"}, format="json")
        assert response.status_code == status.HTTP_200_OK
        banner.refresh_from_db()
        assert banner.title == "Patched Title"

    def test_delete_banner_hard_delete(self, staff_client):
        banner = self._create_banner("Delete Me")
        url = reverse("catalog:admin-banner-detail", kwargs={"pk": banner.pk})
        response = staff_client.delete(url)
        assert response.status_code == status.HTTP_204_NO_CONTENT
        assert not Banner.objects.filter(pk=banner.pk).exists()

    def test_delete_banner_forbidden_for_regular_user(self, regular_client):
        banner = self._create_banner("Protected Banner")
        url = reverse("catalog:admin-banner-detail", kwargs={"pk": banner.pk})
        response = regular_client.delete(url)
        assert response.status_code == status.HTTP_403_FORBIDDEN

    def test_retrieve_banner_forbidden_for_regular_user(self, regular_client):
        banner = self._create_banner("Inaccessible Banner")
        url = reverse("catalog:admin-banner-detail", kwargs={"pk": banner.pk})
        response = regular_client.get(url)
        assert response.status_code == status.HTTP_403_FORBIDDEN
